/* === Reset & Base === */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --cream: #F5F2ED;
  --ink: #1A1A1A;
  --warm-gray: #8C8880;
  --terracotta: #C2795C;
  --sage: #8A9A8A;
  --sand: #D4C9B8;
  --border-light: rgba(26, 26, 26, 0.08);
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 2rem;
  --spacing-lg: 4rem;
  --spacing-xl: 8rem;
  --sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --serif: 'Playfair Display', 'Times New Roman', Georgia, serif;
  --max-text: 640px;
}

html { font-size: 16px; scroll-behavior: smooth; }

body {
  font-family: var(--sans);
  background: var(--cream);
  color: var(--ink);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* === Typography === */
h1, h2, h3, h4 { font-family: var(--serif); font-weight: 400; line-height: 1.15; }
p { margin-bottom: 1.25rem; }

.serif { font-family: var(--serif); }

/* === Header / Navigation === */
.site-header {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 100;
  padding: 1.75rem var(--spacing-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(to bottom, var(--cream) 60%, transparent);
  transition: background 0.3s;
}

.logo {
  font-family: var(--serif);
  font-size: 1.4rem;
  color: var(--ink);
  text-decoration: none;
  letter-spacing: -0.02em;
}

.logo span { font-style: italic; }

.nav-links {
  display: flex;
  gap: 2rem;
  list-style: none;
}

.nav-links a {
  font-family: var(--sans);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--ink);
  text-decoration: none;
  transition: opacity 0.25s;
  font-weight: 500;
}

.nav-links a:hover { opacity: 0.5; }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  z-index: 200;
  background: none;
  border: none;
  padding: 4px;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 1.5px;
  background: var(--ink);
  transition: transform 0.3s, opacity 0.3s;
}

.hamburger.open span:nth-child(1) { transform: translateY(6.5px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-6.5px) rotate(-45deg); }

/* Mobile overlay */
.mobile-nav {
  display: none;
  position: fixed;
  inset: 0;
  background: var(--cream);
  z-index: 150;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2.5rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s;
}

.mobile-nav.open {
  opacity: 1;
  pointer-events: auto;
}

.mobile-nav a {
  font-family: var(--serif);
  font-size: 2.5rem;
  color: var(--ink);
  text-decoration: none;
  transition: opacity 0.25s;
}

.mobile-nav a:hover { opacity: 0.5; }

/* === Sections === */
section { padding: var(--spacing-xl) var(--spacing-lg); }

/* === Hero === */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: flex-end;
  padding-top: 10rem;
  padding-bottom: var(--spacing-lg);
}

.hero h1 {
  font-size: clamp(2.5rem, 6vw, 5rem);
  max-width: 800px;
  letter-spacing: -0.03em;
  line-height: 1.1;
}

/* === Media Showcase === */
.media-showcase {
  padding-top: 0;
  padding-bottom: 0;
}

.showcase-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1px;
  background: var(--border-light);
}

.showcase-block {
  aspect-ratio: 4 / 5;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.showcase-block:nth-child(1) { background: #C2795C; } /* terracotta */
.showcase-block:nth-child(2) { background: #8A9A8A; } /* sage */
.showcase-block:nth-child(3) { background: #D4C9B8; } /* sand */

.showcase-label {
  font-family: var(--serif);
  font-size: 1.1rem;
  color: var(--cream);
  opacity: 0.7;
  letter-spacing: 0.06em;
}

/* === Client Marquee === */
.marquee-section {
  padding: var(--spacing-xl) 0;
  overflow: hidden;
}

.marquee-row {
  display: flex;
  gap: 0;
  overflow: hidden;
  font-family: var(--serif);
  font-size: clamp(2rem, 4.5vw, 3.5rem);
  color: var(--ink);
  line-height: 1.3;
  white-space: nowrap;
  position: relative;
  user-select: none;
}

.marquee-row + .marquee-row { margin-top: 0.25rem; }

.marquee-track {
  display: flex;
  gap: 0;
  animation: marquee var(--duration) linear infinite;
  will-change: transform;
}

.marquee-row:nth-child(even) .marquee-track { animation-direction: reverse; }

.marquee-track span {
  padding: 0 1.5rem;
  display: inline-flex;
  align-items: center;
}

.marquee-track span::after {
  content: '◦';
  padding-left: 1.5rem;
  font-size: 0.6em;
  vertical-align: middle;
  opacity: 0.3;
}

@keyframes marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

/* === About === */
.about {
  padding: var(--spacing-xl) var(--spacing-lg);
}

.about h2 {
  font-family: var(--sans);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  margin-bottom: 2rem;
  color: var(--warm-gray);
  font-weight: 500;
}

.about-content {
  max-width: var(--max-text);
}

.about-content h3 {
  font-size: clamp(1.5rem, 3vw, 2rem);
  margin-bottom: 1.5rem;
  line-height: 1.25;
}

.about-content p {
  font-size: 1.05rem;
  line-height: 1.75;
  color: #3A3A3A;
}

/* === Founder Letter === */
.founder-letter {
  min-height: 100vh;
  padding-top: calc(var(--spacing-xl) + 6rem);
  padding-bottom: var(--spacing-xl);
  display: flex;
  justify-content: center;
}

.letter-container {
  max-width: var(--max-text);
  width: 100%;
}

.letter-date {
  font-family: var(--sans);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--warm-gray);
  margin-bottom: 2rem;
  font-weight: 500;
}

.letter-container h1 {
  font-size: clamp(2rem, 4.5vw, 3.5rem);
  margin-bottom: 3rem;
  letter-spacing: -0.02em;
}

.letter-body p {
  font-size: 1.1rem;
  line-height: 1.85;
  color: #2A2A2A;
  margin-bottom: 1.5rem;
}

.letter-body p:first-of-type { margin-top: 1rem; }

.letter-signature {
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--border-light);
}

.letter-signature p {
  font-family: var(--serif);
  font-size: 1.3rem;
  font-style: italic;
  margin-bottom: 0;
}

/* === Services === */
.philosophy {
  min-height: 60vh;
