  align-items: center;
  padding-top: calc(var(--spacing-xl) + 6rem);
  padding-bottom: var(--spacing-lg);
}

.philosophy-container {
  max-width: var(--max-text);
}

.philosophy-container h1 {
  font-size: clamp(2rem, 4vw, 3.5rem);
  margin-bottom: 2rem;
}

.philosophy-container p {
  font-size: 1.1rem;
  line-height: 1.8;
  color: #2A2A2A;
}

.philosophy-container h2 {
  font-family: var(--serif);
  font-size: clamp(1.8rem, 3.5vw, 3rem);
  font-weight: 400;
  margin-top: 2.5rem;
  margin-bottom: 0;
  letter-spacing: -0.02em;
}

.divider-line {
  border: none;
  border-top: 1px solid var(--border-light);
  margin: 0 var(--spacing-lg);
}

.service-details {
  padding-top: var(--spacing-lg);
}

.service-details h2 {
  font-family: var(--serif);
  font-size: clamp(1.6rem, 3vw, 2.5rem);
  max-width: var(--max-text);
  margin-bottom: 4rem;
  font-weight: 400;
  line-height: 1.3;
}

.services-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem;
  max-width: 1000px;
}

.service-item h3 {
  font-family: var(--serif);
  font-size: 1.5rem;
  margin-bottom: 1rem;
  font-weight: 400;
}

.service-item p {
  font-size: 0.95rem;
  line-height: 1.7;
  color: #3A3A3A;
}

/* === Clients Grid === */
.clients-page {
  padding-top: calc(var(--spacing-xl) + 6rem);
