  font-weight: 400;
  margin-bottom: 0.5rem;
}

.client-card p {
  font-size: 0.9rem;
  line-height: 1.65;
  color: #4A4A4A;
  margin-bottom: 0;
}

/* === Contact === */
.contact-hero {
  min-height: 100vh;
