  display: inline-block;
}

.contact-links a:hover { opacity: 0.4; }

/* === Footer === */
.site-footer {
  padding: var(--spacing-md) var(--spacing-lg);
  border-top: 1px solid var(--border-light);
  display: flex;
  justify-content: space-between;
  font-size: 0.75rem;
  color: var(--warm-gray);
