  letter-spacing: 0.08em;
}

/* === Responsive === */
@media (max-width: 768px) {
  :root {
    --spacing-lg: 2rem;
    --spacing-xl: 4rem;
  }

  .site-header { padding: 1.25rem var(--spacing-md); }

